algorithms.pseudocode:
function ClassifyRegime(n, d):
    d_c       <- 1 - 1/n^2          # critical density
    branching <- n^2 * (1 - d)      # mean legal symbols per free cell
    free      <- n^4 * (1 - d)      # number of free cells
    if  branching > 1: return ('subcritical', d_c, branching, free)
    if  branching = 1: return ('critical',    d_c, branching, free)
    else:              return ('supercritical', d_c, branching, free)
